        ///     <br/>
        ///     <c>void ColorConvertRGBtoHSV(float r, float g, float b, float&amp; out_h, float&amp; out_s, float&amp; out_v)</c>
        ///   </para>
        /// </summary>
        /// <remarks>
        ///   <para>
        ///     Color Utilities
        ///   </para>
        ///   <code>
        ///     Convert rgb floats ([0-1],[0-1],[0-1]) to hsv floats ([0-1],[0-1],[0-1]), from Foley &amp; van Dam p592
        ///     Optimized http://lolengine.net/blog/2013/01/13/fast-rgb-to-hsv
        ///   </code>
        /// </remarks>
        public static unsafe void ColorConvertRGBtoHSV(
            float r,
            float g,
            float b,
            out float outH,
            out float outS,
            out float outV
        )
