            fixed (float* outV_fixed = &outV)
            {
                fixed (float* outS_fixed = &outS)
                {
                    fixed (float* outH_fixed = &outH)
                    {
                        PInvoke.ColorConvertRGBtoHSV(r, g, b, outH_fixed, outS_fixed, outV_fixed);
                    }
                }
            }
        }

