        /// <remarks>
        ///   <para>
        ///     Color Utilities
        ///   </para>
        ///   <code>
        ///     Convert hsv floats ([0-1],[0-1],[0-1]) to rgb floats ([0-1],[0-1],[0-1]), from Foley &amp; van Dam p593
        ///     also http://en.wikipedia.org/wiki/HSL_and_HSV
        ///   </code>
        /// </remarks>
        public static unsafe void ColorConvertHSVtoRGB(
            float h,
            float s,
            float v,
            out float outR,
            out float outG,
            out float outB
